package com.crm.audit.controller;
import com.crm.audit.entity.AuditLog; import com.crm.audit.repository.AuditLogRepository; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/audits") public class AuditController { private final AuditLogRepository repo; public AuditController(AuditLogRepository repo){this.repo=repo;} @GetMapping public List<AuditLog> all(){return repo.findAll();} @GetMapping("/{entityName}/{entityId}") public List<AuditLog> byEntity(@PathVariable String entityName,@PathVariable Long entityId){return repo.findByEntityNameAndEntityIdOrderByCreatedAtDesc(entityName,entityId);} @PostMapping public ResponseEntity<AuditLog> create(@RequestBody AuditLog x){return ResponseEntity.status(HttpStatus.CREATED).body(repo.save(x));} }